const express = require('express');
const app = express();

const users = [
  { id: '1', name: 'Ana' },
  { id: '2', name: 'Bia' },
];

app.get('/users/:id', (req, res) => {
  const user = users.find((u) => u.id === req.params.id);
  if (!user) {
    res.status(404).json({ error: 'not found' });
    return;
  }
  res.json(user);
});

app.listen(3000);

